function Quote-ProcessArgument([string]$Value) {
  if ($null -eq $Value -or $Value.Length -eq 0) { return '""' }
  return '"' + ($Value -replace '(\\*)"', '$1$1\"' -replace '(\\+)$', '$1$1') + '"'
}
function Invoke-SupabaseCliJson([string[]]$Arguments) {
  $command = Get-Command supabase -CommandType Application -ErrorAction Stop
  $info = New-Object System.Diagnostics.ProcessStartInfo
  $info.FileName = if ($command.Path) { $command.Path } else { $command.Source }
  $info.UseShellExecute = $false; $info.CreateNoWindow = $true; $info.RedirectStandardOutput = $true; $info.RedirectStandardError = $true
  $info.Arguments = (($Arguments | ForEach-Object { Quote-ProcessArgument ([string]$_) }) -join ' ')
  $process = New-Object System.Diagnostics.Process; $process.StartInfo = $info
  if (-not $process.Start()) { throw 'Unable to start Supabase CLI.' }
  $outTask = $process.StandardOutput.ReadToEndAsync(); $errTask = $process.StandardError.ReadToEndAsync(); $process.WaitForExit()
  $out = $outTask.GetAwaiter().GetResult(); $err = $errTask.GetAwaiter().GetResult()
  if ($process.ExitCode -ne 0) { throw "Supabase CLI failed with exit code $($process.ExitCode)." }
  try { return ($out | ConvertFrom-Json) } catch {
    $starts = @($out.IndexOf('['), $out.IndexOf('{')) | Where-Object { $_ -ge 0 }; $ends = @($out.LastIndexOf(']'), $out.LastIndexOf('}')) | Where-Object { $_ -ge 0 }
    if ($starts.Count -eq 0 -or $ends.Count -eq 0) { throw 'Supabase CLI returned no JSON payload.' }
    $start = ($starts | Measure-Object -Minimum).Minimum; $end = ($ends | Measure-Object -Maximum).Maximum
    return ($out.Substring($start, $end - $start + 1) | ConvertFrom-Json)
  }
}
function Headers($key, $token = $null) { $h=@{apikey=$key;Authorization="Bearer $key";'Content-Type'='application/json';Prefer='return=representation'}; if($token){$h.Authorization="Bearer $token"}; return $h }
function Raw($method, $url, $headers, $body = $null) {
  try { $p=@{Method=$method;Uri=$url;Headers=$headers;ErrorAction='Stop';UseBasicParsing=$true}; if($null -ne $body){$p.Body=($body|ConvertTo-Json -Depth 40 -Compress)}; $r=Invoke-WebRequest @p; return [pscustomobject]@{status=[int]$r.StatusCode;body=$r.Content} }
  catch { $s=0; if($_.Exception.Response){$s=[int]$_.Exception.Response.StatusCode.value__}; $b=$_.ErrorDetails.Message; if([string]::IsNullOrWhiteSpace($b)){$b=$_.Exception.Message}; return [pscustomobject]@{status=$s;body=$b} }
}
function Json($raw){try{return ($raw.body|ConvertFrom-Json)}catch{return $null}}
function Rpc($name,$payload,$token){return Raw POST "$base/rest/v1/rpc/$name" (Headers $anonKey $token) $payload}
function Denied($raw){return $raw.status -in @(400,401,403,404,409,422)}
function New-Password{$bytes=New-Object byte[] 24;$rng=[Security.Cryptography.RandomNumberGenerator]::Create();try{$rng.GetBytes($bytes)}finally{$rng.Dispose()};return ([Convert]::ToBase64String($bytes)+'Aa9!')}
function SignIn($email,$password){return Json (Raw POST "$base/auth/v1/token?grant_type=password" (Headers $anonKey) @{email=$email;password=$password})}
function Mark($name,$value){$script:results[$name]=[bool]$value}
function ResponseDetails($raw){$p=Json $raw;$c='';$m='';if($p){$c=[string]$p.code;$m=[string]$p.message;if([string]::IsNullOrWhiteSpace($m)){$m=[string]$p.error_description}};if([string]::IsNullOrWhiteSpace($m)){$m=[string]$raw.body};return [pscustomobject]@{code=$c;message=(($m-replace '\s+',' ').Trim());payload=$p}}
function Diagnostic($operation,$identity,$rpcName,$raw,$expected,$actual){$d=ResponseDetails $raw;Write-Output "phase_c_diagnostic=operation:$operation;identity:$identity;rpc:$rpcName;http_status:$($raw.status);pg_code:$($d.code);message:$($d.message);expected:$expected;actual:$actual"}
function Row($raw){@((Json $raw))[0]}
